public static int indexOfLastSeparator(String filename) {
    if (filename == null) return -1;
    int lastIndex = -1;
    int lastSlashIndex = -1;
    int lastBackslashIndex = -1;

    // Check for Unix slashes
    for (int i = 0; i < filename.length(); i++) {
        if (filename.charAt(i) == '/') {
            lastIndex = i;
            lastSlashIndex = i;
        } else if (filename.charAt(i) == '\\') {
            lastIndex = i;
            lastBackslashIndex = i;
        }
    }

    // Check for Windows slashes
    if (lastBackslashIndex == -1) {
        for (int i = 0; i < filename.length(); i++) {
            if (filename.charAt(i) == '\\') {
                lastIndex = i;
                lastBackslashIndex = i;
            }
        }
    }

    // Return the last occurrence of one of the separators
    if (lastSlashIndex > -1 && lastBackslashIndex > -1) {
        return Math.max(lastSlashIndex, lastBackslashIndex);
    }
    return lastIndex;
}

