public static String unescapeJava(String str) throws Exception {
    if (str == null) return null;

    StringBuilder result = new StringBuilder();
    int length = str.length();
    int i = 0;
    while (i < length) {
        char c = str.charAt(i);
        if (c == '\\') {
            i++; // Skip the '\'
            if (i >= length) throw new IllegalArgumentException("Invalid escape sequence");
            char next = str.charAt(i);
            switch (next) {
                case 'n':
                    result.append('\n');
                    break;
                case 'r':
                    result.append('\r');
                    break;
                case '"':
                    result.append('"');
                    break;
                case '\'':
                    result.append('\');
                    break;
                case '\\':
                    result.append('\\');
                    break;
                default:
                    throw new IllegalArgumentException("Invalid escape sequence");
            }
        } else {
            result.append(c);
        }
        i++;
    }
    return result.toString();
}
