public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder escapedStr = new StringBuilder(str);
    int len = escapedStr.length();

    for (int i = len - 1; i >= 0; i--) {
        char c = escapedStr.charAt(i);

        if (c == '\\') {
            int escapeCharPos = i - 1;
            char escapeChar = escapedStr.charAt(escapeCharPos);

            if (escapeChar == '\\' || escapeChar == 'n' || escapeChar == '\'' || escapeChar == '\"') {
                if (i == 0 || escapedStr.charAt(i - 1) == '\\') {
                    continue;
                }

                escapedStr.deleteCharAt(i);
                escapedStr.insert(i, escapeChar);
            }
        }
    }

    return escapedStr.toString();
}

