    int availableBytes = in.available();

    while (bytesRead < availableBytes) {
        int len = Math.min(buffer.length - bytesRead, availableBytes);
        int read = in.read(buffer, bytesRead, len);
        bytesRead += read;

        if (read == -1) {
            throw new EOFException("End of file encountered");
        }
    }

    readPointer = 0;
}

