public int compare(Object aObj1, Object aObj2) {
    if (aObj1 == null && aObj2 == null) {
        return 0;
    } else if (aObj1 == null) {
        return -1;
    } else if (aObj2 == null) {
        return 1;
    } else {
        try {
            // Determine the byte arrays
            byte[] array1 = (byte[]) aObj1;
            byte[] array2 = (byte[]) aObj2;

            // Find the common prefix
            int commonPrefixLength = 0;
            while (commonPrefixLength < array1.length && commonPrefixLength < array2.length
                    && array1[commonPrefixLength] == array2[commonPrefixLength]) {
                commonPrefixLength++;
            }

            // Compare the first differing byte
            if (commonPrefixLength < array1.length && commonPrefixLength < array2.length) {
                return array1[commonPrefixLength] - array2[commonPrefixLength];
            } else {
                // If arrays are not equal, the longer array is considered greater
                if (array1.length > array2.length) {
                    return 1;
                } else {
                    return -1;
                }
            }
        } catch (ClassCastException e) {
            // Handle the case where one object is not of type byte[]
            throw new IllegalArgumentException("Both arguments must be of type byte[]");
        }
    }
}

