static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("Day step must be positive");
    }

    long startYear = timeBucket / (1000 * 3600 * 24); // Start year
    long startMonth = (timeBucket / (1000 * 3600)) % 31; // Start month
    long startDay = timeBucket % (1000 * 3600); // Start day

    startYear += (startMonth - 1) / dayStep; // Adjust start year based on day step

    long compressedTimeBucket = (startYear * 10000000) + (startMonth * (1000 * 3600) / dayStep) + (startDay * 1000);

    return compressedTimeBucket;
}

