public static int computeUTF8Size(CharSequence str, final int index, final int len) {
    int count = 0;
    for (int i = index; i < index + len && i < str.length(); i++) {
        char c = str.charAt(i);
        if (c >= 0xD800 && c < 0xE000) { // High surrogate (looks like "\uD800")
            if (i + 1 < str.length() && str.charAt(i + 1) >= 0xDC00 && str.charAt(i + 1) < 0xE000) { // Low surrogate (looks like "\uDC00")
                count += 2;
                i++; // Skip the low surrogate
            } else {
                throw new IllegalArgumentException("Invalid UTF-8 surrogate pair");
            }
        } else if (c >= 0x80 && c <= 0xBF) { // 1-byte character
            count++;
        } else if (c >= 0xC0 && c <= 0xDF) { // 2-byte character
            count += 2;
        } else if (c >= 0xE0 && c <= 0xEF) { // 3-byte character
            count += 3;
        } else if (c >= 0xF0 && c <= 0xF7) { // 4-byte character
            count += 4;
        } else if (c >= 0xF8 && c <= 0xFD) { // 5-byte character (outside the range of UTF-8)
            throw new IllegalArgumentException("Invalid UTF-8 sequence");
        } else if (c >= 0xFE && c <= 0xFF) { // EOF indicator (at the end of the string)
            return count;
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 character");
        }
    }
    return count;
}

